def clean(df):
    df = df.copy()
    # Clean Price: remove $ and commas, convert to numeric
    if 'Price' in df.columns:
        df['Price'] = df['Price'].astype(str).str.replace(r'[\$,]', '', regex=True).str.strip()
        df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
    # Clean Region: normalize case variants and typos to allowed values
    if 'Region' in df.columns:
        mapping = {'north': 'North', 'nort': 'North', 'south': 'South', 'suoth': 'South', 'east': 'East', 'west': 'West', 'wst': 'West'}
        # lower strip then map
        cleaned = df['Region'].astype(str).str.strip().str.lower().map(mapping)
        # keep mapped values, fallback to original where not mapped (should not happen)
        df['Region'] = cleaned.where(cleaned.notna(), df['Region'])
        allowed = ['North', 'South', 'East', 'West']
        df.loc[~df['Region'].isin(allowed), 'Region'] = pd.NA
    # Clean Date: coerce invalid dates to NaT (e.g., 2026-14-01)
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    # Ensure Quantity numeric
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    return df

def answer(df):
    df = clean(df)
    # drop missing group keys
    df = df.dropna(subset=['Region'])
    grouped = df.groupby('Region')['Quantity'].sum()
    # convert to int where possible
    result = {}
    for k, v in grouped.items():
        if pd.isna(k):
            continue
        # v is numeric sum
        if float(v).is_integer():
            result[str(k)] = int(v)
        else:
            result[str(k)] = float(v)
    return result
